    for root, dirs, files in os.walk('bmj_full'):
        for file in files:
            zf.write(os.path.join(root, file), file)
print('Pages:', downloaded)"; ls -lh bmjservice_sources_complet.zip && wc -c bmjservice_sources_complet.zip",
